## CVXPY SOURCE: utilities/scopes.py
## DPP (Disciplined Parameterized Programming) scope management.
##
## When a DPP scope is active, Parameters are treated as affine (not constant).
## This allows curvature analysis to determine if a problem is DPP-compliant,
## which enables caching the solving chain across parameter value changes.

# -- DPP scope state -------------------------------------------------
## Module-level mutable state for DPP scope (reference semantics via environment).
##
## Thread Safety:
## `.dpp_state` is module-level mutable state (single boolean). It is NOT
## thread-safe. Concurrent calls to `with_dpp_scope()` (e.g., via `future`
## with forked workers) would corrupt state. This is acceptable because:
## 1. R is single-threaded by default.
## 2. CVXR does not support parallel backends.
## 3. `withr::local_*` would not help -- the issue is shared state, not cleanup.
## If parallel support is ever added, this would need a per-thread or
## per-session scope mechanism.

.dpp_state <- new.env(parent = emptyenv())
.dpp_state$active <- FALSE

#' Check if DPP Scope is Active
#'
#' @returns Logical; \code{TRUE} if a \code{with_dpp_scope} block is active.
#' @keywords internal
dpp_scope_active <- function() .dpp_state$active

#' Execute Expression Within DPP Scope
#'
#' Within this scope, \code{Parameter} objects are treated as affine
#' (not constant) for curvature analysis. This is used internally by
#' \code{is_dpp()} to check DPP compliance.
#'
#' @param expr An R expression to evaluate within the DPP scope.
#' @returns The result of evaluating \code{expr}.
#' @keywords internal
with_dpp_scope <- function(expr) {
  prev <- .dpp_state$active
  .dpp_state$active <- TRUE
  on.exit(.dpp_state$active <- prev)
  force(expr)
}

# -- quad_form DPP scope ---------------------------------------------
## CVXPY v1.9.0 #3142: a SEPARATE scope for quad_form DPP analysis with QP
## solvers. When active, QuadForm.is_atom_convex/concave() relaxes the
## P.is_constant() requirement, allowing a parametric P matrix for solvers
## that handle quadratic objectives directly. The solving chain enters it
## when a quad-obj-capable solver is selected.
##
## This mirrors scopes.py's manager/query pair. The broader #3142 behavior
## (QuadForm relaxation + coeff_extractor parametric-P handling + solving-chain
## reordering) is a larger feature tracked separately; the scope state itself
## is provided here for API parity and so callers can gate that behavior.
.quad_form_dpp_state <- new.env(parent = emptyenv())
.quad_form_dpp_state$active <- FALSE

#' Check if a quad_form DPP Scope is Active
#'
#' @returns Logical; \code{TRUE} if a \code{with_quad_form_dpp_scope} block is active.
#' @keywords internal
quad_form_dpp_scope_active <- function() .quad_form_dpp_state$active

#' Execute Expression Within a quad_form DPP Scope
#'
#' @param expr An R expression to evaluate within the quad_form DPP scope.
#' @returns The result of evaluating \code{expr}.
#' @keywords internal
with_quad_form_dpp_scope <- function(expr) {
  prev <- .quad_form_dpp_state$active
  .quad_form_dpp_state$active <- TRUE
  on.exit(.quad_form_dpp_state$active <- prev)
  force(expr)
}

# -- DPP-aware cache key helper --------------------------------------
## Returns a scope-suffixed cache key so curvature/DCP results computed under
## a scope are cached SEPARATELY from out-of-scope results. This is
## staleness-critical: a curvature value computed inside quad_form_dpp_scope
## (where a parametric P is treated as affine) must never be returned to an
## out-of-scope caller, and vice versa.
##
## Four states, mirroring CVXPY performance_utils.py's suffix logic:
##   <key>            -- no scope
##   <key>_dpp        -- dpp_scope only
##   <key>_qfdpp      -- quad_form_dpp_scope only
##   <key>_dpp_qfdpp  -- both
## Fast path: the overwhelmingly common no-scope case returns base_key with
## no allocation; suffixing only happens during is_dpp() checks.
##
## PERF (v1.9): when a scope IS active, the suffixed key is MEMOIZED per base_key
## (computed once into a length-4 variant vector) instead of rebuilt with paste0
## on every call. is_dpp() walks the whole expression tree querying many cached
## curvature predicates under scope; the per-call paste0 was a measurable cost on
## node-dense problems (it is also the dominant residual for genuinely parametric
## problems, which keep a scope-active pass -- see
## notes/v19_perf_regression_dpp_rootcause.md). The returned KEY STRINGS are
## byte-identical to the old paste0 logic, so all cache semantics are unchanged.
## (Mirrors the precomputed-lookup approach used by the 1.8.2 .dpp_keys table,
## generalized to the 4-state quad_form_dpp space.)
.dpp_key_variants <- new.env(parent = emptyenv())  # base_key -> c(base, _dpp, _qfdpp, _dpp_qfdpp)
.dpp_key <- function(base_key) {
  d <- .dpp_state$active
  q <- .quad_form_dpp_state$active
  if (!d && !q) return(base_key)                   # fast path: no scope, no alloc
  v <- .dpp_key_variants[[base_key]]
  if (is.null(v)) {
    v <- c(base_key,
           paste0(base_key, "_dpp"),
           paste0(base_key, "_qfdpp"),
           paste0(base_key, "_dpp_qfdpp"))
    .dpp_key_variants[[base_key]] <- v
  }
  ## index 2 = dpp only, 3 = qfdpp only, 4 = both (1 = neither, unreached here).
  v[[1L + d + 2L * q]]
}
